TIET_HAN = {"冬至": "Đông Chí", "小寒": "Tiểu Hàn", "大寒": "Đại Hàn", "立春": "Lập Xuân", "雨水": "Vũ Thủy",
            "惊蛰": "Kinh Trập", "春分": "Xuân Phân", "清明": "Thanh Minh", "谷雨": "Cốc Vũ", "立夏": "Lập Hạ",
            "小满": "Tiểu Mãn", "芒种": "Mang Chủng", "夏至": "Hạ Chí", "小暑": "Tiểu Thử", "大暑": "Đại Thử",
