VONG = [1, 8, 3, 4, 9, 2, 7, 6]           # 8 cung ngoài theo chiều kim đồng hồ: Khảm Cấn Chấn Tốn Ly Khôn Đoài Càn
CUNG = {1: "Khảm (Bắc)", 2: "Khôn (Tây Nam)", 3: "Chấn (Đông)", 4: "Tốn (Đông Nam)", 5: "Trung cung",
