    print("VƯỢNG SUY NHẬT CHỦ – CHẤM ĐIỂM HAI THANG (tham khảo cho bước chọn dụng thần)")
    print("- Tứ trụ: " + ", ".join("%s %s" % (nh, B.vn(g + z)) for nh, g, z in tru)
          + ("" if len(tru) == 4 else " (không có trụ giờ: điểm kém tin cậy)"))
