        for i in range(0, len(LunarUtil.ZHI)):
            zhi = LunarUtil.ZHI[i]
            if time_zhi == zhi:
                time_zhi_index = i
                break
        offset = month_zhi_index + time_zhi_index
        if offset > 12:
            offset -= 12
        gan_index = (self.__lunar.getYearGanIndexExact() + 1) * 2 + offset
        while gan_index > 10:
